import type {YamlFile} from './rule-util'
import type {TemplateResult} from 'lit-html'
import {html} from 'lit-html'
import leven from 'leven'
import yaml from 'js-yaml'
import type {Validation} from '../linter-util'

// eslint-disable-next-line @typescript-eslint/no-explicit-any
function objectKeys(obj: any): string[] {
  if (obj == null || typeof obj !== 'object' || Array.isArray(obj)) return []
  return Object.keys(obj)
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
function findNode(result: any, path: string[]): any {
  let cursor = result
  for (const key of path) {
    if (typeof cursor !== 'object' || cursor == null) return null
    cursor = cursor[key]
  }
  return cursor
}

function keysForPath(result: unknown, path: string[]): string[] {
  return objectKeys(findNode(result, path))
}

function codeTag(value: string): TemplateResult {
  return html` <code>${value}</code> `
}

function joinCodeTags(values: string[]): TemplateResult {
  return html` ${values.map((value, i) => html` ${i > 0 ? ', ' : ''}${codeTag(value)} `)} `
}

function getIndentation(line: string): string {
  const match = line.match(/^\s*/)
  return match ? match[0] : ''
}

export function replaceWhitespaces(text: string, tab: string, ind: string) {
  return text.replace(/\t/g, tab).replace(/\n/g, `\n${ind}`)
}

function containsExpression(str: string): boolean {
  return str.includes('${{')
}

// Checks if a github supported expression is used.
function isExpressionFunction(str: string): boolean {
  const regexPattern = /\${{\s*(fromJSON|toJSON|contains|startsWith|endsWith|format|join)\((.*)\)\s*}}/
  const isExpressionRegex = new RegExp(regexPattern, 'i')
  return str.match(isExpressionRegex) != null
}

// Check if a string contains a fromJSON expression, matches on ${{ fromJSON(<arbitary_content>) }}
function isFromJsonExpression(str: string): boolean {
  const fromJSONExpression = new RegExp(/\${{\s*fromJSON\((.*)\)\s*}}/, 'i')
  return str.match(fromJSONExpression) != null
}

// Get expression content ${{ github.run_id }}_${{matrix.id}}_result: words -> [ 'github.run_id', 'matrix.id']
// This function gets the content between expression brackets ${{<this_content>}} and doesn't relate to expression
// functions like fromJSON, toJSON, format, etc.
function getExpressionContexts(str: string): string[] {
  const contextExpression = new RegExp(/\${{(.+?)}}/, 'g')
  const matches: string[] = []
  let match: RegExpExecArray | null
  while ((match = contextExpression.exec(str)) !== null) {
    matches.push(match[1]?.trim() as string)
  }

  return matches
}

// 'test ${{ inputs.input1 - inputs.input2 }}' => ['inputs.input1', 'inputs.input2']
function extractInputsExpressions(str: string): string[] {
  const results: string[] = []

  // 'test ${{ inputs.input1 }}' => ['${{ inputs.input1 }}']
  const expressionSyntaxArray = str.match(/\${{([^}]*)}}/g) || []
  for (const expressionSyntax of expressionSyntaxArray) {
    // '${{ inputs.input1 }}' => 'inputs.input1'
    const inputsExpressions = expressionSyntax.match(/inputs\.([^\s}]+)/g) || []
    for (const inputExpression of inputsExpressions) {
      results.push(inputExpression)
    }
  }

  return results
}

function isStringWithExpressions(str: string): boolean {
  const expressionsRemovedStr = str.replace(/\${{([^}]*)}}/g, '').trim()
  return expressionsRemovedStr !== ''
}

/*
 * In order to simplify the autocomplete algorithm this function deletes part of the text that are no relevant
 * to what the user is typing. Specifically it removes lines that have greater or equal indentation than the current line
 * with the exception of lines starting with "-"
 */
function getSimplifiedText(textBeforeCursor: string): {simplifiedText: string; lastLine: string} {
  const lines = textBeforeCursor.split('\n')
  const lastLine = lines[lines.length - 1]!
  const indentation = getIndentation(lastLine)
  const lineStartsWithDash = lastLine.substring(indentation.length).startsWith('-')

  const simplified = lines.slice(0, lines.length - 1).map(ln => {
    const lineIndentation = getIndentation(ln)
    // If the indentation is greater, we don't care about this line
    if (lineIndentation.length > indentation.length) return ''
    // If the identation is the same, we only care about this line
    // the line is important if the last line (current one) starts an array element. e.g.
    // steps:
    // - id: foo # the previous line has the same indentation. If this line didn't start with - we would not care about the previous one
    if (lineIndentation.length === indentation.length && !lineStartsWithDash) return ''
    // Check if this line is for an array element
    const remaining = ln.substring(lineIndentation.length)
    const arrStart = remaining.match(/^-\s+/)
    if (arrStart && lineIndentation.length + arrStart[0].length >= indentation.length) {
      const totalIndentationLength = lineIndentation.length + arrStart[0].length
      // If the indentation is greater, we don't care about this line
      if (totalIndentationLength > indentation.length) return ''
      // If the indentation is the same, we care abut it being an array, but not about the rest of the content
      if (totalIndentationLength === indentation.length) return `${lineIndentation}-`
    }
    return ln
  })
  simplified.push(lastLine)
  return {simplifiedText: simplified.join('\n'), lastLine}
}

/*
 * Returns the path and current value of the node the user is editing.
 * Returns the latest and deepest node in the data structure. This is possible to do this way because
 * we only have in consideration the text before the cursor and we simplify the document by removing all
 * lines with greater indentation than the current line.
 */
// eslint-disable-next-line @typescript-eslint/no-explicit-any
function getCurrentNode(result: any): {path: string[]; lastValue: string} {
  const path = []
  let obj = result
  while (obj && typeof obj === 'object') {
    const keys = Object.keys(obj)
    const key = keys[keys.length - 1]!
    path.push(key)
    obj = obj[key]
  }
  const lastValue = obj != null ? String(obj) : ''
  return {path, lastValue}
}

/*
 * Parses the document and tries to fix small malformed defects such as `on: [push` (no closing bracket because the user is typing).
 * Since the user may be typing in the middle of the file, we need the content split into the part before the cursor (`start` argument) and
 * after it (`end` argument).
 */
function parse(start: string, end: string): {result: unknown; lastValue?: string; consumeKey: boolean} {
  try {
    return {result: yaml.load(start + end), consumeKey: false}
  } catch (err) {
    // @ts-expect-error catch blocks are bound to `unknown` so we need to validate the type before using it
    const {message} = err
    if (message.includes('mapping')) {
      const match = start.match(/\w+$/)
      return {result: yaml.load(`${start}:${end}`), lastValue: match ? match[0] : undefined, consumeKey: true}
    }
    if (message.includes('collection')) {
      const match = start.match(/,\s*$/)
      let full = match ? start.substring(0, start.length - match[0].length) : start
      full += end.match(/^\]/) ? end : ']'
      const lastValue = match ? '' : undefined
      return {result: yaml.load(full), lastValue, consumeKey: true}
    }
    throw err
  }
}

function similarity(a: string, b: string): number {
  const value = leven(a, b)
  if (a.endsWith('-latest')) return value - 1
  return value
}

function sortBySimilarity(values: string[], currentValue: string): string[] {
  return values.sort((a, b) => similarity(a, currentValue) - similarity(b, currentValue))
}

const validateGlob = async (yamlContent: YamlFile, path: string[], value: unknown): Promise<Validation | undefined> => {
  if (typeof value !== 'string') return
  const scanner: Scanner = new Scanner(value)
  while (!scanner.atEnd()) {
    const escape = scanner.scan(escapeRegex)
    if (escape !== null && escape[0] === '\\') {
      return toHtmlError('trailing backslash')
      continue
    }

    const stars = scanner.scan(starsRegex)
    if (stars !== null) {
      if (stars[0].length > 2) return toHtmlError('too many sequential * characters')
      if (scanner.isNext('+')) return toHtmlError('+ cannot follow *')
      if (scanner.isNext('?')) return toHtmlError('? cannot follow *')
      continue
    }

    const questionMarks = scanner.scan(questionMarksRegex)
    if (questionMarks !== null) {
      if (questionMarks[0].length > 1) return toHtmlError('? cannot follow ?')
      continue
    }

    const pluses = scanner.scan(plusesRegex)
    if (pluses !== null) {
      if (pluses[0].length > 1) return toHtmlError('+ cannot follow +')
      if (scanner.isNext('?')) return toHtmlError('? cannot follow +')
      continue
    }

    if (scanner.isNext('[')) {
      scanner.takeOne()
      const rangeContent = scanner.scan(rangeContentRegex)

      if (rangeContent === null) return toHtmlError('empty character range')
      if (!scanner.isNext(']')) return toHtmlError('unterminated character range')
      if (!rangeContent[0].match(validRangeContentRegex)) return toHtmlError('invalid character range')

      scanner.takeOne()
      continue
    }

    scanner.takeOne()
  }
}

const escapeRegex = /^\\.?/
const plusesRegex = /^\++/
const questionMarksRegex = /^\?+/
const starsRegex = /^\*+/
const rangeContentRegex = /^[^\]]+/ // Anything but ]
// Optional ^ followed by one or more of: single digit or letter, digit range, letter range
const validRangeContentRegex = /^\^?(?:(?:\d(?:-\d)?)|(?:[a-z](?:-[a-z])?))+$/i

function toHtmlError(message: string) {
  return {
    message: html` ${message} `,
    severity: 'error',
  }
}

class Scanner {
  value: string

  constructor(value: string) {
    this.value = value
  }

  atEnd(): boolean {
    return this.value.length === 0
  }

  isNext(char: string): boolean {
    return this.value[0] === char
  }

  scan(regex: RegExp): RegExpMatchArray | null {
    const result = this.value.match(regex)
    if (result !== null) {
      this.value = this.value.substring(result[0].length)
    }
    return result
  }

  takeOne(): string {
    this.value = this.value.substring(1)
    return this.value[0]!
  }
}

export {
  codeTag,
  containsExpression,
  joinCodeTags,
  findNode,
  getIndentation,
  keysForPath,
  parse,
  getCurrentNode,
  getExpressionContexts,
  getSimplifiedText,
  sortBySimilarity,
  validateGlob,
  isFromJsonExpression,
  extractInputsExpressions,
  isStringWithExpressions,
  isExpressionFunction,
}
